script:
(function () {
  'use strict';
  // Boat loan: monthly payment from the price, or the affordable price from a monthly budget.
  //   Down payment D = d% of price or a dollar amount.
  //   Taxable amount = price - trade-in value (when the trade-in credit box is ticked), never below 0.
  //   Loan = price - D - trade-in + owed on trade-in (+ sales tax and fees when financed).
  //   Payment: M = L * i / (1 - (1 + i)^-n), i = APR / 12, n = years * 12 (M = L / n at 0%).
  //   Affordable price: L = M * (1 - (1 + i)^-n) / i, then the loan equation is solved for the price
  //   (it is linear in the price: P = (L + D$ + trade - owed - f*fees - f*t*credit) / (1 - d% + f*t)).
  // Verified in Node (scratchpad tests/w2loans): $35,000 boat, $7,000 down, 7% for 10 years, 7% tax
  //   and $2,000 fees paid upfront = $325.10/mo, total interest $11,012.45, due upfront $11,450,
  //   total cost $50,462.45 (matches a published boat loan calculator's default); price mode run on
  //   that payment returns $35,000; $12,000 at 0% for 1 year = $1,000/mo; no NaN on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function loanFromPayment(pmt, annualRate, months) {
    var i = annualRate / 12;
    if (i === 0) return pmt * months;
    return pmt * (1 - Math.pow(1 + i, -months)) / i;
  }

  // Everything that depends on the price, for a given set of inputs.
  function costs(price, o) {
    var down = o.downPercent ? price * o.down / 100 : o.down;
    var taxable = Math.max(0, price - (o.tradeCredit ? o.trade : 0));
    var tax = taxable * o.taxRate / 100;
    var loan = price - down - o.trade + o.owed + (o.finance ? tax + o.fees : 0);
    return { price: price, down: down, tax: tax, loan: loan };
  }

  // Price whose loan amount equals the target (the loan equation is linear in the price).
  function priceForLoan(loan, o) {
    var t = o.taxRate / 100, f = o.finance ? 1 : 0, dPct = o.downPercent ? o.down / 100 : 0, dAmt = o.downPercent ? 0 : o.down;
    var credit = o.tradeCredit ? o.trade : 0;
    var p = (loan + dAmt + o.trade - o.owed - f * o.fees + f * t * credit) / (1 - dPct + f * t);
    if (f && p < credit) p = (loan + dAmt + o.trade - o.owed - o.fees) / (1 - dPct);
    return p;
  }

  function amortize(loan, annualRate, months) {
    var pay = monthlyPayment(loan, annualRate, months);
    var i = annualRate / 12, bal = loan, rows = [], totalInterest = 0;
    for (var m = 1; m <= months && bal > 0.005; m++) {
      var interest = bal * i;
      var principal = Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      rows.push({ n: m, interest: interest, principal: principal, balance: bal });
    }
    return { payment: pay, rows: rows, totalInterest: totalInterest };
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['btMain', 'btLoan', 'btInterest', 'btTotalCost', 'btPriceOut', 'btPaymentOut', 'btDownOut', 'btTax',
     'btUpfront', 'btTotalPayments'].forEach(function (id) { setText(id, '–'); });
    el('btNegative').hidden = true;
    el('btSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var head = el('btScheduleHead'), body = el('btSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var html = [];
    if (el('btView').value === 'month') {
      head.innerHTML = '<tr><th scope="col">Month</th><th scope="col">Payment</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Balance</th></tr>';
      last.rows.forEach(function (row) {
        html.push('<tr><td>' + row.n + '</td><td>' + money.format(row.principal + row.interest) + '</td><td>' +
          money.format(row.principal) + '</td><td>' + money.format(row.interest) + '</td><td>' + money.format(row.balance) + '</td></tr>');
      });
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Ending balance</th></tr>';
      var p = 0, intr = 0;
      last.rows.forEach(function (row, idx) {
        p += row.principal; intr += row.interest;
        if (row.n % 12 === 0 || idx === last.rows.length - 1) {
          html.push('<tr><td>' + Math.ceil(row.n / 12) + '</td><td>' + money.format(p) + '</td><td>' +
            money.format(intr) + '</td><td>' + money.format(row.balance) + '</td></tr>');
          p = 0; intr = 0;
        }
      });
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var mode = el('btMode').value, priceMode = mode === 'price';
    el('btPriceWrap').hidden = priceMode;
    el('btBudgetWrap').hidden = !priceMode;
    var o = {
      down: read('btDown', true), downPercent: el('btDownUnit').value === 'percent', trade: read('btTrade', true),
      owed: read('btOwed', true), taxRate: read('btTaxRate', true), fees: read('btFees', true),
      finance: el('btFinanceCosts').checked, tradeCredit: el('btTradeCredit').checked
    };
    var price = read('btPrice'), budget = read('btBudget'), rate = read('btRate'), years = read('btTerm');
    setText('btDownHint', o.downPercent ? 'Percent of the boat price. Many lenders ask for 10% to 20%.' : 'Cash you pay toward the boat at purchase.');
    var error = el('btError'), msg = '';
    if (!priceMode && (isNaN(price) || price <= 0)) msg = 'Enter a boat price greater than $0.';
    else if (priceMode && (isNaN(budget) || budget <= 0)) msg = 'Enter a monthly payment greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (isNaN(years) || years < 1 || years > 25 || years % 1 !== 0) msg = 'Enter a loan term of 1 to 25 whole years.';
    else if ([o.down, o.trade, o.owed, o.taxRate, o.fees].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.downPercent && o.down >= 100) msg = 'Enter a down payment below 100% of the price.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }

    var months = years * 12, r = rate / 100, c;
    if (priceMode) {
      var target = loanFromPayment(budget, r, months);
      c = costs(priceForLoan(target, o), o);
      if (!(c.price > 0) || !isFinite(c.price)) msg = 'That payment is too small to cover the trade-in balance and costs you are financing.';
    } else {
      c = costs(price, o);
      if (c.loan <= 0.005) msg = 'Your down payment and trade-in cover the full cost, so there is nothing to finance.';
    }
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    var a = amortize(c.loan, r, months);
    var upfront = c.down + (o.finance ? 0 : c.tax + o.fees);
    setText('btMainLabel', priceMode ? 'Boat price you can afford' : 'Monthly payment');
    setText('btMain', money.format(priceMode ? c.price : a.payment));
    setText('btLoan', money.format(c.loan));
    setText('btInterest', money.format(a.totalInterest));
    setText('btTotalCost', money.format(c.price + c.tax + o.fees + a.totalInterest));
    setText('btPriceOut', money.format(c.price));
    setText('btPaymentOut', money.format(a.payment));
    setText('btDownOut', money.format(c.down));
    setText('btTax', money.format(c.tax));
    setText('btUpfront', money.format(upfront));
    setText('btTotalPayments', money.format(c.loan + a.totalInterest));
    el('btNegative').hidden = !(o.owed > o.trade);
    setText('btNegativeAmount', money.format(Math.max(0, o.owed - o.trade)));
    last = { rows: a.rows };
    renderSchedule();
  }

  function switchDownUnit() {
    var v = read('btDown', true), price = el('btMode').value === 'price' ? NaN : read('btPrice');
    if (!isNaN(v) && price > 0) {
      el('btDown').value = el('btDownUnit').value === 'percent' ? String(Math.round(v / price * 10000) / 100) : String(Math.round(price * v / 100));
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('btForm');
    if (!form) return;
    el('btDownUnit').addEventListener('change', switchDownUnit);
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('btView').addEventListener('change', renderSchedule);
    update();
  });
})();
